package main

import "fmt"

// Point is a named struct type with two exported fields.
type Point struct {
	X int
	Y int
}

// byValue receives a COPY of the struct; mutations are lost.
func byValue(p Point) {
	p.X = 100 // only changes the local copy
}

// byPointer receives the ADDRESS; mutations affect the caller's value.
func byPointer(p *Point) {
	p.X = 100 // p.X is shorthand for (*p).X (automatic dereference)
}

func main() {
	// 1. Zero value: every field defaults to its type's zero (0 here).
	var zero Point
	fmt.Println("zero value:", zero) // {0 0}

	// 2. Positional literal: fields in declaration order.
	pos := Point{3, 4}

	// 3. Named literal: order-independent, omitted fields stay zero.
	named := Point{Y: 7}
	fmt.Println("positional:", pos, "named:", named) // {3 4} {0 7}

	// 4. new(T) returns *T pointing at a zero value.
	ptr := new(Point)
	ptr.X = 1 // automatic dereference through the pointer
	fmt.Println("new pointer:", *ptr) // {1 0}

	// Value vs pointer semantics:
	v := Point{1, 1}
	byValue(v)
	fmt.Println("after byValue:", v) // {1 1} — unchanged
	byPointer(&v)
	fmt.Println("after byPointer:", v) // {100 1} — changed
}

codeExamples.expectedOutput:
zero value: {0 0}
positional: {3 4} named: {0 7}
new pointer: {1 0}
after byValue: {1 1}
after byPointer: {100 1}

