package main

import "fmt"

type Counter struct {
	count int
	name  string
}

// Value receiver: operates on a COPY, cannot mutate the original.
// Good for read-only methods on small structs.
func (c Counter) Value() int {
	return c.count
}

// Pointer receiver: operates on the ORIGINAL, can mutate it.
func (c *Counter) Inc() {
	c.count++ // modifies the struct the pointer refers to
}

// Stringer is satisfied via a pointer receiver here.
func (c *Counter) String() string {
	return fmt.Sprintf("%s=%d", c.name, c.count)
}

func main() {
	c := Counter{name: "hits"}

	// Go auto-takes the address for addressable values:
	// c.Inc() is sugar for (&c).Inc().
	c.Inc()
	c.Inc()
	c.Inc()
	fmt.Println("count:", c.Value()) // 3

	// Calling a pointer-receiver method through a pointer is explicit.
	p := &c
	p.Inc()
	fmt.Println("via pointer:", p.String()) // hits=4

	// A value receiver method on a copy leaves the original alone.
	copyC := c
	copyC.Inc()
	fmt.Println("original still:", c.Value(), "copy:", copyC.Value()) // 4 5
}

package main

import (
	"encoding/json"
	"fmt"
)

// Base carries common fields and a promoted method.
type Base struct {
	ID      int    `json:"id"`
	Created string `json:"created,omitempty"`
}

func (b Base) Describe() string {
	return fmt.Sprintf("record #%d", b.ID)
}

// User embeds Base, promoting Base.ID, Base.Created, and Base.Describe.
type User struct {
	Base            // embedded (anonymous) field
	Name     string `json:"name"`
	Email    string `json:"email"`
	Password string `json:"-"`            // never marshaled
	Age      int    `json:"age,omitempty"` // omitted when zero
}

func main() {
	u := User{
		Base:  Base{ID: 7},
		Name:  "Ada",
		Email: "ada@example.com",
		// Age left at 0 -> omitted; Password set but ignored.
		Password: "s3cr3t",
	}

	// Promoted field and method work directly on the outer type.
	fmt.Println("promoted ID:", u.ID, "-", u.Describe()) // 7 - record #7

	// Marshal to JSON; tags control keys, omitempty, and exclusion.
	out, _ := json.Marshal(u)
	fmt.Println(string(out))

	// Unmarshal back into a fresh struct.
	data := []byte(`{"id":9,"name":"Lin","email":"lin@x.io","age":30}`)
	var got User
	if err := json.Unmarshal(data, &got); err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Printf("unmarshaled: %+v\n", got)
}

