package main

import "fmt"

// Coord has only comparable fields, so it is comparable and usable as a key.
type Coord struct {
	Lat, Lng int
}

func main() {
	a := Coord{10, 20}
	b := Coord{10, 20}
	c := Coord{0, 0}
	fmt.Println("a == b:", a == b, "| a == c:", a == c) // true | false

	// Struct as a map key: counts visits per coordinate.
	visits := map[Coord]int{}
	visits[a]++
	visits[b]++ // same key as a
	visits[c]++
	fmt.Println("visits at {10 20}:", visits[Coord{10, 20}]) // 2

	// Empty struct{} occupies 0 bytes -> ideal set element.
	seen := map[string]struct{}{}
	for _, w := range []string{"go", "go", "rust"} {
		seen[w] = struct{}{}
	}
	_, ok := seen["go"]
	fmt.Println("set size:", len(seen), "| has go:", ok) // 2 | true
}
